INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(91135480, 'Time Thief Double Barrel', '时潜怪盗・双盒芯', 'クロノダイバー・ダブルバレル', 'XYZ Monster', 'Psychic', 'DARK', 4, 2200, 2200, '4星怪兽×2 这个卡名的效果1回合只能使用1次。 ①：对方把效果发动时才能发动。这张卡的超量素材最多3种类（怪兽·魔法·陷阱）取除。那之后，以下适用。 ●怪兽：这张卡的攻击力上升400。 ●魔法：选对方场上1只表侧表示怪兽直到结束阶段得到控制权。这个回合，那只怪兽不能攻击宣言，不能把效果发动。 ●陷阱：选场上1只效果怪兽，那个效果直到回合结束时无效。'),
(18678554, 'Time Thief Flyback', '时潜怪盗・飞返', 'クロノダイバー・フライバック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只「时间潜行者」超量怪兽为对象才能发动。从手卡·卡组选1张「时间潜行者」卡在作为对象的怪兽下面重叠作为超量素材。 ②：把墓地的这张卡除外，以自己场上1只「时间潜行者」超量怪兽为对象才能发动。从对方墓地选1张卡在作为对象的怪兽下面重叠作为超量素材。'),
(81670445, 'Time Thief Hack', '时潜怪盗・停秒', 'クロノダイバー・ハック', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己场上的超量怪兽在特殊召唤的回合不会成为对方的效果的对象，不会被对方的效果破坏。 ②：以自己场上1只超量怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升那些超量素材数量×300。并且那只怪兽有原本持有者是对方的卡在作为超量素材的场合，更在这个回合让那只怪兽可以直接攻击。'),
(59208943, 'Time Thief Perpetua', '时潜怪盗・永恒驱动者', 'クロノダイバー・パーペチュア', 'XYZ Monster', 'Psychic', 'DARK', 4, 1900, 2500, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的准备阶段把这张卡1个超量素材取除，以「时间潜行者·恒动上链员」以外的自己墓地1只「时间潜行者」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：以这张卡以外的自己场上1只超量怪兽为对象才能发动。从卡组选1张「时间潜行者」卡在作为对象的怪兽下面重叠作为超量素材。这个效果在对方回合也能发动。'),
(42620460, 'Time Thief Power Reserve', '时潜怪盗・动力储备', 'クロノダイバー・パワーリザーブ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡发动后变成通常怪兽（念动力族·暗·4星·攻1900/守2500）在怪兽区域特殊召唤（也当作陷阱卡使用）。那之后，可以从自己的手卡·卡组·墓地把1只机械族「时间潜行者」怪兽特殊召唤。 ②：有魔法卡和陷阱卡在作为超量素材中的超量怪兽在自己场上存在的场合，把墓地的这张卡除外才能发动。场上1张卡除外。'),
(55285840, 'Time Thief Redoer', '时潜怪盗・盘面重造者', 'クロノダイバー・リダン', 'XYZ Monster', 'Psychic', 'DARK', 4, 2400, 2000, '4星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：自己·对方的准备阶段才能发动。把对方卡组最上面的卡作为这张卡的超量素材。 ②：自己·对方回合可以发动。这张卡的超量素材最多3种类（怪兽·魔法·陷阱）取除。那之后，那些种类的以下效果适用。 ●怪兽：这张卡直到结束阶段除外。 ●魔法：自己抽1张。 ●陷阱：对方场上1张表侧表示卡回到卡组最上面。'),
(19891131, 'Time Thief Regulator', '时潜怪盗・规范器', 'クロノダイバー・レギュレーター', 'Effect Monster', 'Machine', 'DARK', 4, 600, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有这张卡以外的怪兽存在的场合，把这张卡解放才能发动。从卡组把「时间潜行者规范针表犬」以外的2只「时间潜行者」怪兽守备表示特殊召唤（同名卡最多1张）。 ②：这张卡在墓地存在的状态，自己的超量怪兽被战斗破坏时才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(76587747, 'Time Thief Retrograde', '时潜怪盗・逆跳', 'クロノダイバー・レトログラード', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「时间潜行者」超量怪兽存在，魔法·陷阱卡发动时才能发动。那个发动无效，那张卡在自己场上的「时间潜行者」超量怪兽下面重叠作为超量素材。'),
(10877309, 'Time Thief Startup', '时潜怪盗・起动', 'クロノダイバー・スタートアップ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从手卡把1只「时间潜行者」怪兽特殊召唤。 ②：自己主要阶段把墓地的这张卡除外，以自己场上1只「时间潜行者」超量怪兽为对象才能发动。从自己墓地选「时间潜行者」卡3种类（怪兽·魔法·陷阱）各1张在作为对象的怪兽下面重叠作为超量素材。'),
(52083044, 'Time Thief Temporwhal', '时潜怪盗・摆轮飞鲸', 'クロノダイバー・テンプホエーラー', 'Effect Monster', 'Machine', 'DARK', 4, 800, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放，以对方场上1只怪兽为对象才能发动。那只怪兽直到结束阶段除外。 ②：这张卡在墓地存在的场合，以「时间潜行者摆轮救生艇」以外的自己场上1只「时间潜行者」怪兽为对象才能发动。那只怪兽回到持有者手卡，这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(56308388, 'Time Thief Winder', '时潜怪盗・扭转者', 'クロノダイバー・リューズ', 'Effect Monster', 'Psychic', 'DARK', 4, 1800, 1300, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1个超量素材取除才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「时间潜行者·表冠操作员」以外的1张「时间潜行者」卡加入手卡。'),
(68490573, 'Time to Stand Up', '宏大之魂', '大いなる魂', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：场上有龙族同调怪兽存在的场合才能发动。从卡组把「共鸣者」怪兽或龙族·1星怪兽合计最多2只特殊召唤。 ②：自己场上有10星以上的龙族·暗属性同调怪兽存在，怪兽的效果发动时，把墓地的这张卡除外才能发动。那个效果无效，自己场上1只同调怪兽的攻击力直到下个回合的结束时上升2000。'),
(71625222, 'Time Wizard', '时间魔术师', '時の魔術師', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 500, 400, '①：1回合1次，自己主要阶段才能发动。进行1次投掷硬币，对里表作猜测。猜中的场合，对方场上的怪兽全部破坏。猜错的场合，自己场上的怪兽全部破坏，自己受到表侧表示破坏的怪兽的攻击力合计数值一半的伤害。'),
(26273196, 'Time Wizard of Tomorrow', '时间魔导士', '時の魔導士', 'Fusion Monster', 'Spellcaster', 'LIGHT', 5, 2000, 1900, '「时间魔术师」＋效果怪兽 ①：1回合1次，这张卡是已融合召唤的场合才能发动。进行1次投掷硬币，对里表作猜测。猜中的场合，场上的怪兽全部破坏，对方受到表侧表示破坏的怪兽的原本攻击力合计数值一半的伤害。猜错的场合，场上的怪兽全部破坏，自己受到表侧表示破坏的怪兽的原本攻击力合计数值一半的伤害。'),
(2055403, 'Time-Space Trap Hole', '时光落穴', '時空の落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方从手卡·额外卡组把怪兽特殊召唤时才能发动。从手卡·额外卡组特殊召唤的那些怪兽回到持有者卡组。那之后，自己失去回去的怪兽数量×1000基本分。'),
(19403423, 'Time-Tearing Morganite', '撕裂时间的绿柱魔瞳', '時を裂く魔瞳', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：这次决斗中，以下效果各适用。 ●自己不能把手卡的怪兽的效果发动。 ●自己抽卡阶段的通常抽卡变成2张。 ●自己1回合可以进行通常召唤最多2次。 ②：把墓地的这张卡除外，从手卡丢弃1张「撕裂时间的魔瞳」才能发动。这个回合，在自己怪兽的召唤成功时对方不能把怪兽的效果发动。'),
(44913552, 'Timeater', '时间吞噬者', 'タイム・イーター', 'Effect Monster', 'Machine', 'DARK', 6, 1900, 1700, '这张卡战斗破坏对方怪兽的场合，下次的对方回合的主要阶段1跳过。'),
(80335817, 'Timebreaker Magician', '刻剑之魔术师', '刻剣の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 3, 1400, NULL, '①：只让手卡的这张卡灵摆召唤成功时才能发动。这张卡的攻击力变成原本攻击力的2倍。 ②：1回合1次，以场上1只怪兽为对象才能发动。那只怪兽和场上的这张卡直到下次的自己准备阶段除外。'),
(20409757, 'Timegazer Magician', '时读的魔术师', '時読みの魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 3, 1200, 600, '①：只要这张卡在怪兽区域存在，1回合1次，自己的灵摆区域的卡不会被对方的效果破坏。'),
(67508932, 'Timelord Progenitor Vorpgate', '时械神祖 武加大', '時械神祖ヴルガータ', 'Synchro Monster', 'Fairy', 'DARK', 10, NULL, NULL, '调整＋调整以外的怪兽1只以上 ①：这张卡不会被战斗·效果破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ②：从额外卡组特殊召唤的这张卡进行战斗的伤害步骤结束时才能发动。对方场上的怪兽全部除外。这个效果的发动后，直到回合结束时对方受到的战斗伤害变成一半。 ③：这张卡的②的效果发动的回合的结束阶段发动。那个效果由自己来除外的怪兽尽可能在对方场上特殊召唤。'),
(47349116, 'Timestar Magician', '星刻的魔术师', '星刻の魔術師', 'XYZ Monster', 'Spellcaster', 'DARK', 4, 2400, 1200, '4星「魔术师」灵摆怪兽×2 这张卡用以上记的卡为超量素材的超量召唤才能从额外卡组特殊召唤。 ①：1回合1次，把这张卡1个超量素材取除才能发动。从自己的卡组·额外卡组（表侧）·墓地把1只魔法师族·暗属性怪兽加入手卡。 ②：1回合1次，自己的怪兽区域·灵摆区域的灵摆怪兽卡被战斗·效果破坏的场合，可以作为代替从自己卡组把1只魔法师族怪兽送去墓地。'),
(40350910, 'Timidity', '癔病风', 'おくびょうかぜ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '直到下次的对方回合的结束阶段，场上的盖放的魔法·陷阱不能破坏。'),
(66506689, 'Tin Archduke', '铁皮大公', 'ブリキの大公', 'XYZ Monster', 'Machine', 'EARTH', 4, 2200, 1200, '4星怪兽×3 1回合1次，把这张卡1个超量素材取除，选择对方场上1只怪兽才能发动。选择的怪兽的表示形式变更。这个时候，反转效果怪兽的效果不发动。这个效果在对方回合也能发动。'),
(18063928, 'Tin Goldfish', '铁皮金鱼', 'ブリキンギョ', 'Effect Monster', 'Machine', 'WATER', 4, 800, 2000, '①：这张卡召唤成功时才能发动。从手卡把1只4星怪兽特殊召唤。'),
(75119040, 'Tindangle Acute Cerberus', '廷达魔三角之锐角地狱犬', 'ティンダングル・アキュート・ケルベロス', 'Link Monster', 'Fiend', 'DARK', NULL, NULL, NULL, '「廷达魔三角」怪兽3只 ①：自己墓地有包含「廷达魔三角之底边守卫者」的「廷达魔三角」怪兽3种类以上存在的场合，这张卡的攻击力上升3000。 ②：这张卡的攻击力上升这张卡所连接区的「廷达魔三角」怪兽数量×500。 ③：这张卡攻击宣言的战斗阶段结束时才能发动。在自己场上把1只「廷达魔三角衍生物」（恶魔族·暗·1星·攻/守0）特殊召唤。'),
(68860936, 'Tindangle Angel', '廷达魔三角之天使', 'ティンダングル・エンジェル', 'Flip Effect Monster', 'Fiend', 'DARK', 4, 500, 1800, '这个卡名的效果1回合只能使用1次。 ①：这张卡反转的场合才能发动。从自己的手卡·墓地选「廷达魔三角之天使」以外的1只反转怪兽里侧守备表示特殊召唤。这个效果在对方回合的战斗阶段发动的场合，再把那次战斗阶段结束。'),
(94365540, 'Tindangle Base Gardna', '廷达魔三角之底边守卫者', 'ティンダングル・ベース・ガードナー', 'Effect Monster', 'Fiend', 'DARK', 5, NULL, 2300, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有里侧守备表示怪兽存在的场合，这张卡可以从手卡守备表示特殊召唤。 ②：这张卡已在怪兽区域存在的状态，对方的连接怪兽的所连接区有怪兽召唤·特殊召唤的场合，把这张卡解放才能发动。从手卡·卡组把1只「廷达魔三角」怪兽表侧攻击表示或者里侧守备表示特殊召唤。'),
(99157310, 'Tindangle Delaunay', '廷达魔三角的德劳内三角化', 'ティンダングル・ドロネー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己墓地有「廷达魔三角」怪兽3种类以上存在，对方怪兽的攻击让自己受到战斗伤害时才能发动。那只攻击怪兽破坏，从额外卡组把1只「廷达魔三角之锐角地狱犬」特殊召唤。 ②：额外怪兽区域没有自己怪兽存在的场合，把墓地的这张卡除外，以自己墓地3只「廷达魔三角」怪兽为对象才能发动（同名卡最多1张）。那些怪兽里侧守备表示特殊召唤。'),
(12678601, 'Tindangle Dholes', '廷达魔三角之巨噬蠕虫', 'ティンダングル・ドールス', 'Flip Effect Monster', 'Fiend', 'DARK', 5, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从手卡·卡组送去墓地的场合，以「廷达魔三角之巨噬蠕虫」以外的自己墓地1只「廷达魔三角」怪兽为对象才能发动。那只怪兽里侧守备表示特殊召唤。 ②：这张卡反转的场合才能发动。从卡组把1张魔法·陷阱卡送去墓地。 ③：这张卡为连接素材的「廷达魔三角」连接怪兽在同1次的战斗阶段中可以作3次攻击。'),
(31759689, 'Tindangle Hound', '廷达魔三角之猎犬', 'ティンダングル・ハウンド', 'Flip Effect Monster', 'Fiend', 'DARK', 7, 2500, NULL, '①：这张卡反转的场合，以这张卡以外的场上1只表侧表示怪兽为对象才能发动。这张卡的攻击力上升作为对象的怪兽的原本攻击力数值。那之后，作为对象的怪兽变成里侧守备表示。 ②：对方场上的怪兽的攻击力下降和那怪兽成为连接状态的怪兽数量×1000。 ③：这张卡被战斗·效果破坏送去墓地的场合，以场上1只里侧表示怪兽为对象才能发动。那只怪兽变成表侧守备表示。'),
(94142993, 'Tindangle Intruder', '廷达魔三角之侵入者', 'ティンダングル・イントルーダー', 'Flip Effect Monster', 'Fiend', 'DARK', 6, 2200, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡反转的场合才能发动。从卡组把1张「廷达魔三角」卡加入手卡。 ②：这张卡召唤成功时才能发动。从卡组把1张「廷达魔三角」卡送去墓地。 ③：这张卡在墓地存在，自己场上有怪兽里侧守备表示特殊召唤的场合发动。这张卡从墓地里侧守备表示特殊召唤。'),
(24158464, 'Tindangle Jhrelth', '廷达魔三角之结界石', 'ティンダングル・ジレルス', 'Flip Effect Monster', 'Fiend', 'DARK', 3, NULL, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡的场合，把这张卡以外的1张手卡丢弃才能发动。从卡组把「廷达魔三角之结界石」以外的1张「廷达魔三角」卡送去墓地，这张卡里侧守备表示特殊召唤。 ②：这张卡反转的场合才能发动。从卡组选「廷达魔三角之结界石」以外的1只反转怪兽加入手卡或送去墓地。'),
(67744384, 'Tindangle Protector', '廷达魔三角之使徒', 'ティンダングル・アポストル', 'Flip Effect Monster', 'Fiend', 'DARK', 3, 800, 1600, '这个卡名的效果1回合只能使用1次。 ①：这张卡反转的场合才能发动。选自己场上最多3只里侧表示怪兽变成表侧守备表示。这个效果变成表侧守备表示的怪兽全部是「廷达魔三角」怪兽的场合，可以把最多有那些怪兽数量的「廷达魔三角」卡从卡组加入手卡。'),
(75119041, 'Tindangle Token', '廷达魔三角之锐角地狱犬', 'ティンダングル・アキュート・ケルベロス', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(11375683, 'Tindangle Trinity', '廷达魔三角之三位一体', 'ティンダングル・トリニティ', 'Flip Effect Monster', 'Fiend', 'DARK', 4, NULL, 1500, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡反转的场合才能发动。从卡组把1只「廷达魔三角之底边守卫者」特殊召唤。 ②：只要反转过的这张卡在怪兽区域存在，自己的「廷达魔三角」怪兽不会被战斗破坏。 ③：这张卡作为「廷达魔三角」连接怪兽的连接素材送去墓地的场合才能发动。从卡组把1张「热尔岗终焉」加入手卡，从卡组把1张魔法·陷阱卡送去墓地。'),
(85640370, 'Tip of the Tinying Tongue', '舌尖短少', '舌先減少', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方把宣言1个卡名发动的效果发动时才能发动。那个效果无效。那之后，自己可以把宣言的1张卡从卡组加入手卡。 ②：盖放的这张卡被对方的效果破坏的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力下降500。'),
(31386180, 'Tiras, Keeper of Genesis', '始祖保卫者提拉斯', '始祖の守護者ティラス', 'XYZ Monster', 'Fairy', 'LIGHT', 5, 2600, 1700, '5星怪兽×2 这张卡的效果只在这张卡持有超量素材的场合适用。 ①：场上的这张卡不会被效果破坏。 ②：这张卡进行战斗的战斗阶段结束时，以对方场上1张卡为对象发动。那张对方的卡破坏。 ③：自己结束阶段发动。这张卡1个超量素材取除。'),
(54387923, 'TiSolfachord Beautia', '西音服和弦・尤提娅', 'シドレミコード・ビューティア', 'Pendulum Effect Monster', 'Fairy', 'EARTH', 7, 2500, 2400, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：自己·对方回合，以对方场上1只效果怪兽为对象才能发动。这个回合，那张卡从场上离开的场合除外。自己的灵摆区域有偶数的灵摆刻度存在的场合，也能以对方场上1张表侧表示的魔法·陷阱卡为对象。 ②：1回合1次，这张卡和持有自己的灵摆区域的最低灵摆刻度×300以上的攻击力的怪兽进行战斗的伤害步骤开始时发动。那只怪兽破坏。'),
(87676171, 'Tistina, the Divinity that Defies Darkness', '蚀神之光 提斯蒂娜', '神蝕む光 ティスティナ', 'XYZ Monster', 'Aqua', 'LIGHT', 10, 2000, 3000, '10星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合才能发动。对方场上的里侧表示卡全部送去墓地。 ②：这张卡有「结晶神 提斯蒂娜」在作为超量素材的场合，1回合1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力直到对方回合结束时上升2000。 ③：持有超量素材的这张卡被对方破坏的场合才能发动。从自己墓地把1只「提斯蒂娜」怪兽特殊召唤。'),
(41373230, 'Titaniklad the Ash Dragon', '灰烬龙 落尘劣种', '灰燼竜バスタード', 'Fusion Monster', 'Dragon', 'DARK', 8, 2500, 2500, '「阿不思的落胤」＋攻击力2500以上的怪兽 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力上升作为这张卡的融合素材的怪兽的原本等级合计×100。 ②：这张卡融合召唤时适用。这个回合，这张卡不受从额外卡组特殊召唤的其他怪兽发动的效果影响。 ③：这张卡被送去墓地的回合的结束阶段才能发动。从卡组选1只「教导」怪兽或「阿不思的落胤」加入手卡或特殊召唤。'),
(67037924, 'Titanocider', '巨神封印之矢', '巨神封じの矢', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以从额外卡组特殊召唤的对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0，那个效果无效。 ②：这张卡在墓地存在的状态，对方从额外卡组把怪兽特殊召唤的场合才能发动。这张卡在自己场上盖放。这个效果在这张卡送去墓地的回合不能发动。'),
(82319644, 'Tlakalel, His Malevolent Majesty', '邪王 特拉卡埃莱尔', '邪王トラカレル', 'Effect Monster', 'Fiend', 'DARK', 5, 2400, 1000, '①：这张卡上级召唤成功的场合才能发动。攻击力合计最多到为这张卡的上级召唤而解放的怪兽的原本攻击力以下为止，选对方场上的表侧表示怪兽任意数量破坏。'),
(62671448, 'Toad Master', '蛤蟆仙人', 'トードマスター', 'Normal Monster', 'Aqua', 'WATER', 3, 1000, 1000, '活了几千年的青蛙仙人。用蝌蚪进行攻击。'),
(90809975, 'Toadally Awesome', '饼蛙', '餅カエル', 'XYZ Monster', 'Aqua', 'WATER', 2, 2200, NULL, '水族2星怪兽×2 ①：双方的准备阶段把这张卡1个超量素材取除才能发动。从卡组把1只「青蛙」怪兽特殊召唤。 ②：1回合1次，对方把怪兽的效果·魔法·陷阱卡发动时，把自己的手卡·场上1只水族怪兽送去墓地才能发动。那个发动无效并破坏。那之后，可以把破坏的卡在自己场上盖放。 ③：这张卡被送去墓地的场合，以自己墓地1只水属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(31887806, 'Tobari the Sky Ninja', '宙之忍者-鸟帷', '宙の忍者－鳥帷', 'Effect Monster', 'Winged Beast', 'EARTH', 1, NULL, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：把这张卡从手卡送去墓地才能发动。从手卡把1只「忍者」怪兽表侧守备表示或者里侧守备表示特殊召唤。 ②：这张卡在特殊召唤·反转的回合不会被战斗·效果破坏。 ③：对方的主要阶段以及战斗阶段才能发动。从自己的手卡·场上把「忍者」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(30118701, 'Todoroki the Earthbolt Star', '地雷星 轰', '地雷星トドロキ', 'Effect Monster', 'Warrior', 'EARTH', 6, 2100, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把手卡1只其他怪兽送去墓地，从手卡特殊召唤。这个方法特殊召唤的这张卡的攻击力下降500。 ②：自己·对方的战斗阶段支付500基本分才能发动。从自己的手卡·场上把战士族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(33878931, 'Togex', '撞击兽', 'クラッシュマン', 'Normal Monster', 'Beast', 'EARTH', 5, 1600, 1800, '动作意外地敏捷，把身体卷成圆形进行撞击。'),
(95072744, 'Tohushaddoll Grysta', '英雄之烬影依 古利水晶', '影雄の烬 エグリスタ', 'Flip Effect Monster', 'Rock', 'EARTH', 7, 2450, 1950, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合，以岩石族以外的自己墓地1只「影依」怪兽为对象才能发动。那只怪兽的反转的场合发动的效果适用。 ②：这张卡被效果送去墓地的场合才能发动（这个效果发动的回合，自己不是「影依」怪兽不能从额外卡组特殊召唤）。自己的手卡·场上·墓地的怪兽作为融合素材除外，把1只「影依」融合怪兽融合召唤。'),
(43534808, 'Token Collector', '衍生物收藏家', 'トークンコレクター', 'Effect Monster', 'Fiend', 'EARTH', 4, NULL, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，衍生物特殊召唤的场合才能发动。这张卡特殊召唤。 ②：这张卡特殊召唤成功的场合发动。场上的衍生物全部破坏，这张卡的攻击力上升破坏的衍生物数量×400。 ③：只要这张卡在怪兽区域存在，双方不能把衍生物特殊召唤。'),
(83675475, 'Token Feastevil', '衍生物谢肉祭', 'トークン謝肉祭', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '衍生物特殊召唤时发动。场上存在的全部衍生物破坏，与对方基本分破坏的衍生物数量×300分的伤害。'),
(14342283, 'Token Stampede', '暴走斗君', '暴走闘君', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，攻击表示的衍生物攻击力上升1000，不会被战斗破坏。'),
(52971673, 'Token Sundae', '衍生物复活祭', 'トークン復活祭', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的衍生物全部破坏。把最多有这个效果破坏的衍生物数量的场上存在的卡破坏。'),
(53545926, 'Token Support', '共斗斗君', '共闘闘君', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：把自己场上的衍生物任意数量解放，以自己场上1只攻击力0的怪兽为对象才能发动。那只怪兽直到回合结束时攻击力上升解放数量×1000，同1次的战斗阶段中可以向怪兽作出最多有解放数量的攻击。 ②：对方战斗阶段结束时才能发动。把最多有这次战斗阶段中被破坏的衍生物数量的「共斗衍生物」（兽族·地·1星·攻/守0）在自己场上特殊召唤。'),
(57182235, 'Token Thanksgiving', '衍生物收获祭', 'トークン収穫祭', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '破坏场上所有衍生物。回复破坏衍生物数量×800的基本分。'),
(82361206, 'Tokkosho of Ghost Destroying', '灵灭独钴杵', '霊滅独鈷杵', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽给与对方基本分战斗伤害时，可以选择对方墓地存在的最多2只怪兽从游戏中除外。'),
(50357013, 'Tokusano Shinkyojin', '十种神镜阵', '十種神鏡陣', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：等级合计直到变成10星为止，从自己的手卡·场上（表侧表示）把怪兽任意数量送去墓地才能发动。自己抽2张。'),
(82003859, 'Toll', '通行税', '通行税', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '双方玩家若不支付500基本分，则不能攻击宣言。'),
(44716890, 'Toll Hike', '通行增税', '通行増税', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：双方玩家若不把1张手卡送去墓地则不能攻击宣言。'),
(300101005, 'Tomb of the Pharaoh', NULL, NULL, 'Skill Card', 'Ishizu', NULL, NULL, NULL, NULL, NULL),
(46457856, 'Tomozaurus', '死党恐龙', 'トモザウルス', 'Normal Monster', 'Dinosaur', 'EARTH', 2, 500, 400, '体形虽然小，但性格凶暴。经常和同伴相争。'),
(91250514, 'Tongue Twister', '绕舌怪', 'タン・ツイスター', 'Effect Monster', 'Fiend', 'DARK', 6, 400, 300, '上级召唤的这张卡从场上送去墓地时，从自己卡组抽2张卡。这个效果发动的场合，这张卡从游戏中除外。'),
(69572024, 'Tongyo', '舌鱼', '舌魚', 'Normal Monster', 'Fish', 'WATER', 4, 1350, 800, '用长舌头抓住其他的鱼，吸取能量。'),
(70508653, 'Tool Box', '工作箱', '工作箱', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有怪兽存在的场合才能发动。从卡组把2张卡名不同的装备魔法卡给对方观看，对方从那之中随机选1张。那1张卡加入自己手卡，剩下的卡回到卡组最下面。'),
(59383041, 'Toon Alligator', '卡通鳄鱼', 'トゥーン・アリゲーター', 'Normal Monster', 'Reptile', 'WATER', 4, 800, 1600, '从美国卡通世界中出现的鳄鱼型怪兽。'),
(7171149, 'Toon Ancient Gear Golem', '卡通古代的机械巨人', 'トゥーン・アンティーク・ギアゴーレム', 'Toon Monster', 'Machine', 'EARTH', 8, 3000, 3000, '①：这张卡在召唤·反转召唤·特殊召唤的回合不能攻击。 ②：自己场上有「卡通世界」存在，对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。 ③：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ④：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(28112535, 'Toon Barrel Dragon', '卡通左轮手枪龙', 'トゥーン・リボルバー・ドラゴン', 'Toon Monster', 'Machine', 'DARK', 7, 2600, 2200, '①：这张卡在召唤·反转召唤·特殊召唤的回合不能攻击。 ②：自己场上有「卡通世界」存在，对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。 ③：1回合1次，以场上1张卡为对象才能发动。进行3次投掷硬币，那之内2次以上是表的场合，那张卡破坏。'),
(28711704, 'Toon Black Luster Soldier', '卡通混沌战士', 'トゥーン・カオス・ソルジャー', 'Toon Monster', 'Warrior', 'EARTH', 8, 3000, 2500, '这张卡不能通常召唤。从自己的手卡·场上把等级合计直到8以上的卡通怪兽解放的场合可以特殊召唤。 ①：自己场上有「卡通世界」存在，对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。 ②：1回合1次，自己场上有「卡通世界」存在的场合，以场上1张卡为对象才能发动。那张卡除外。这个效果发动的回合，这张卡不能攻击。'),
(91500017, 'Toon Bookmark', '卡通书签', 'トゥーンのしおり', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把1张「卡通书签」以外的有「卡通世界」的卡名记述的卡或者「卡通世界」从卡组加入手卡。 ②：自己场上的「卡通世界」被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(5832914, 'Toon Briefcase', '卡通手提箱', 'トゥーンのかばん', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有卡通怪兽存在，对方把怪兽召唤·反转召唤·特殊召唤时才能发动。那些怪兽回到持有者卡组。'),
(61190918, 'Toon Buster Blader', '卡通破坏之剑士', 'トゥーン・バスター・ブレイダー', 'Toon Monster', 'Warrior', 'EARTH', 7, 2600, 2300, '①：这张卡的攻击力上升对方的场上·墓地的龙族怪兽数量×500。 ②：这张卡在召唤·反转召唤·特殊召唤的回合不能攻击。 ③：自己场上有「卡通世界」存在，对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。'),
(79875176, 'Toon Cannon Soldier', '卡通加农炮兵', 'トゥーン・キャノン・ソルジャー', 'Toon Monster', 'Machine', 'DARK', 4, 1400, 1300, '这张卡召唤·反转召唤·特殊召唤的回合不能攻击。自己场上有「卡通世界」存在，对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。场上的「卡通世界」被破坏时这张卡也破坏。可以把自己场上存在的1只怪兽解放，给与对方基本分500分伤害。'),
(83629030, 'Toon Cyber Dragon', '卡通电子龙', 'トゥーン・サイバー・ドラゴン', 'Toon Monster', 'Machine', 'LIGHT', 5, 2100, 1600, '①：对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡在召唤·反转召唤·特殊召唤的回合不能攻击。 ③：自己场上有「卡通世界」存在，对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。'),
(21296502, 'Toon Dark Magician', '卡通黑魔术师', 'トゥーン・ブラック・マジシャン', 'Toon Monster', 'Spellcaster', 'DARK', 7, 2500, 2100, '①：这张卡在召唤·反转召唤·特殊召唤的回合不能攻击。 ②：自己场上有「卡通世界」存在，对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。 ③：1回合1次，可以从手卡丢弃1张「卡通」卡，从以下效果选择1个发动。 ●从卡组把「卡通黑魔术师」以外的1只卡通怪兽无视召唤条件特殊召唤。 ●从卡组把1张「卡通」魔法·陷阱卡加入手卡。'),
(90960358, 'Toon Dark Magician Girl', '卡通黑魔术少女', 'トゥーン・ブラック・マジシャン・ガール', 'Toon Monster', 'Spellcaster', 'DARK', 6, 2000, 1700, '这张卡不能通常召唤。自己场上有「卡通世界」存在的状态，把自己场上1只怪兽解放的场合可以特殊召唤。 ①：这张卡的攻击力上升双方墓地的「黑魔术师」「黑混沌之魔术师」数量×300。 ②：这张卡在对方场上没有卡通怪兽存在的场合，可以直接攻击。存在的场合，只能选择卡通怪兽作为攻击对象。 ③：场上的「卡通世界」被破坏时这张卡破坏。'),
(43509019, 'Toon Defense', '卡通防御', 'トゥーン・ディフェンス', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方怪兽向自己的4星以下的卡通怪兽攻击宣言时才能把这个效果发动。那只对方怪兽的攻击变成对自己的直接攻击。'),
(42386471, 'Toon Gemini Elf', '卡通双生精灵', 'トゥーン・ヂェミナイ・エルフ', 'Toon Monster', 'Spellcaster', 'EARTH', 4, 1900, 900, '①：这张卡在召唤·反转召唤·特殊召唤的回合不能攻击。 ②：自己场上有「卡通世界」存在，对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。 ③：这张卡给与对方战斗伤害时才能发动。对方手卡随机选1张丢弃。 ④：场上的「卡通世界」被破坏时这张卡破坏。'),
(15270885, 'Toon Goblin Attack Force', '卡通哥布林突击部队', 'トゥーン・ゴブリン突撃部隊', 'Toon Monster', 'Warrior', 'EARTH', 4, 2300, NULL, '这张卡召唤·反转召唤·特殊召唤的回合不能攻击。场上的「卡通世界」被破坏时这张卡也破坏。自己场上有「卡通世界」且对方不控制卡通的场合，这张卡可以直接攻击对方玩家。这张卡攻击的场合在战斗阶段结束时守备表示，在下次的自己的回合结束前不能改变这张卡的表示形式。'),
(64116319, 'Toon Harpie Lady', '卡通鹰身女郎', 'トゥーン・ハーピィ・レディ', 'Toon Monster', 'Winged Beast', 'WIND', 4, 1300, 1400, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有「卡通世界」存在的场合才能发动。这张卡从手卡特殊召唤。自己场上有其他的卡通怪兽存在的场合，可以再选对方场上1张魔法·陷阱卡破坏。 ②：这张卡在召唤·反转召唤·特殊召唤的回合不能攻击。 ③：自己场上有「卡通世界」存在，对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。'),
(43175858, 'Toon Kingdom', '卡通王国', 'トゥーン・キングダム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，从自己卡组上面把3张卡里侧表示除外。 ②：这张卡只要在场地区域存在，卡名当作「卡通世界」使用。 ③：只要这张卡在场地区域存在，自己场上的卡通怪兽不会成为对方的效果的对象。 ④：自己场上的卡通怪兽被战斗·效果破坏的场合，可以作为代替把破坏的怪兽每1只1张卡从自己卡组上面里侧表示除外。'),
(79447365, 'Toon Mask', '卡通面具', 'トゥーン・マスク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「卡通世界」存在的场合，以对方场上1只表侧表示怪兽为对象才能发动。把持有那只怪兽的等级或者阶级的数值以下的等级的1只卡通怪兽无视召唤条件从手卡·卡组特殊召唤。'),
(16392422, 'Toon Masked Sorcerer', '卡通假面魔道士', 'トゥーン・仮面魔道士', 'Toon Monster', 'Spellcaster', 'DARK', 4, 900, 1400, '这张卡召唤·反转召唤·特殊召唤的回合不能攻击。场上的「卡通世界」被破坏时这张卡也破坏。自己场上有「卡通世界」且对方不控制卡通的场合，这张卡可以直接攻击对方玩家。这张卡造成对方伤害时，这张卡的持有者抽1张卡。'),
(300204004, 'Toon Mayhem!', NULL, NULL, 'Skill Card', 'Pegasus', NULL, NULL, NULL, NULL, NULL),
(65458948, 'Toon Mermaid', '卡通人鱼', 'トゥーン・マーメイド', 'Toon Monster', 'Aqua', 'WATER', 4, 1400, 1500, '这张卡不能通常召唤。自己场上有「卡通世界」存在的场合可以特殊召唤。 ①：这张卡在特殊召唤的回合不能攻击。 ②：这张卡若不支付500基本分则不能攻击宣言。 ③：对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。存在的场合，必须把卡通怪兽作为攻击对象。 ④：场上的「卡通世界」被破坏时这张卡破坏。'),
(27699122, 'Toon Page-Flip', '卡通翻阅', 'トゥーン・フリップ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「卡通世界」存在的场合才能发动。从卡组把3只卡名不同的卡通怪兽给对方观看，对方从那之中随机选1只。那1只怪兽无视召唤条件在自己场上特殊召唤。剩下的怪兽回到卡组。'),
(70560957, 'Toon Rollback', '卡通倒带', 'トゥーン・ロールバック', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只卡通怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击。'),
(91842653, 'Toon Summoned Skull', '卡通恶魔', 'トゥーン・デーモン', 'Toon Monster', 'Fiend', 'DARK', 6, 2500, 1200, '这张卡不能通常召唤。自己场上有「卡通世界」存在的场合才能特殊召唤（5星以上需要解放）。这张卡在特殊召唤的回合不能攻击。这张卡若不支付500基本分则不能攻击宣言。对方场上不存在卡通怪兽的场合，这张卡可以直接攻击对方玩家。存在的场合，必须选择卡通怪兽作为攻击对象。场上的「卡通世界」被破坏时，这张卡破坏。'),
(89997728, 'Toon Table of Contents', '卡通目录', 'トゥーンのもくじ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1张「卡通」卡加入手卡。'),
(53094821, 'Toon Terror', '卡通叙述者', 'トゥーン・テラー', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「卡通世界」以及卡通怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(15259703, 'Toon World', '卡通世界', 'トゥーン・ワールド', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '支付1000基本分才能把这张卡发动。'),
(53623827, 'Top Runner', '领跑者', 'トップ・ランナー', 'Tuner Monster', 'Machine', 'WIND', 4, 1100, 800, '只要这张卡在场上表侧表示存在，自己场上表侧表示存在的全部同调怪兽的攻击力上升600。'),
(90359458, 'Top Share', '顶级份享', 'トップ・シェア', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组选1张卡，给双方确认并在卡组最上面放置。那之后，对方从自身卡组选1张卡，给双方确认并在自身卡组最上面放置。'),
(30064423, 'Topologic Blaster Dragon', '拓扑逻辑冲击龙', 'トポロジック・ブラスター・ドラゴン', 'Link Monster', 'Cyberse', 'DARK', NULL, 3500, NULL, '效果怪兽2只以上 自己不能在作为这张卡所连接区的额外怪兽区域让怪兽出现。 ①：这张卡在额外怪兽区域存在的状态，连接怪兽所连接区有怪兽特殊召唤的场合发动。从以下效果选1个适用。这个回合，自己的「拓扑冲击波龙」的效果不能有相同效果适用。 ●这张卡以外的场上的怪兽全部回到卡组。 ●场上的魔法·陷阱卡全部回到卡组。 ●把对方的额外卡组确认，那之内的1张除外。'),
(5821478, 'Topologic Bomber Dragon', '拓扑逻辑轰炸龙', 'トポロジック・ボマー・ドラゴン', 'Link Monster', 'Cyberse', 'DARK', NULL, 3000, NULL, '效果怪兽2只以上 ①：这张卡已在怪兽区域存在的状态，这张卡以外的怪兽在连接怪兽所连接区特殊召唤的场合发动。双方的主要怪兽区域的怪兽全部破坏。这个回合，这张卡以外的自己怪兽不能攻击。 ②：这张卡向对方怪兽攻击的伤害计算后发动。给与对方那只对方怪兽的原本攻击力数值的伤害。'),
(22593417, 'Topologic Gumblar Dragon', '拓扑篡改感染龙', 'トポロジック・ガンブラー・ドラゴン', 'Link Monster', 'Cyberse', 'DARK', NULL, 3000, NULL, '效果怪兽2只以上 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡已在怪兽区域存在的状态，这张卡以外的怪兽在连接怪兽所连接区特殊召唤的场合发动。自己把手卡任意数量随机丢弃（最多2张）。那之后，对方选丢弃数量的手卡丢弃。 ②：这张卡是额外连接状态的场合才能发动。对方尽可能选最多2张手卡丢弃。这个效果让对方手卡变成0张的场合，再给与对方3000伤害。'),
(72529749, 'Topologic Trisbaena', '拓扑逻辑三叶双头蛇', 'トポロジック・トゥリスバエナ', 'Link Monster', 'Cyberse', 'DARK', NULL, 2500, NULL, '效果怪兽2只以上 ①：这张卡所连接区有怪兽特殊召唤的场合发动。那些怪兽以及场上的魔法·陷阱卡全部除外，给与对方这个效果除外的对方的卡数量×500伤害。'),
(66403530, 'Topologic Zeroboros', '拓扑逻辑零衔尾蛇', 'トポロジック・ゼロヴォロス', 'Link Monster', 'Cyberse', 'DARK', NULL, 3000, NULL, '效果怪兽2只以上 自己不能在作为这张卡所连接区的额外怪兽区域让怪兽出现。 ①：这张卡的攻击力上升除外状态的卡数量×200。 ②：这张卡在怪兽区域存在的状态，连接怪兽所连接区有怪兽特殊召唤的场合发动。场上的卡全部除外。 ③：这张卡被自身的效果除外的场合，下个回合的准备阶段发动。除外状态的这张卡特殊召唤。'),
(83370323, 'Torapart', '陷阱颠倒者', 'トラパート', 'Tuner Monster', 'Warrior', 'DARK', 2, 600, 600, '这张卡为同调素材的同调怪兽攻击的场合，对方直到伤害步骤结束时陷阱卡不能发动。把这张卡作为同调素材的场合，不是战士族怪兽的同调召唤不能使用。'),
(80813021, 'Torike', '犀牛', 'サイガー', 'Normal Monster', 'Beast', 'EARTH', 3, 1200, 600, '虽然守备不像外表般高强。但是角的攻击力还是很强。'),
(59160189, 'Torment Token', '暗黑世界－暗影恶托邦', '闇黒世界－シャドウ・ディストピア－', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(61068510, 'Tornado', '大龙卷', 'トルネード', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '对方的魔法与陷阱卡区域卡有3张以上存在时才能发动。对方的魔法与陷阱卡区域存在的1张卡破坏。'),
(71283180, 'Tornado Bird', '龙卷鸟', 'トルネード・バード', 'Flip Effect Monster', 'Winged Beast', 'WIND', 4, 1100, 1000, '反转：场上的魔法·陷阱卡2张回主人的手卡。'),
(6983839, 'Tornado Dragon', '龙卷龙', '竜巻竜', 'XYZ Monster', 'Wyrm', 'WIND', 4, 2100, 2000, '4星怪兽×2 ①：自己·对方回合1次，把这张卡1个超量素材取除，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(18605135, 'Tornado Wall', '龙卷海流壁', '竜巻海流壁', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '场上有「海」存在的场合才能把这张卡发动。 ①：只要场上有「海」存在，自己受到的战斗伤害变成0。 ②：场上没有「海」存在的场合这张卡破坏。'),
(90337190, 'Torpedo Fish', '鱼雷鱼', '魚雷魚', 'Effect Monster', 'Fish', 'WATER', 3, 1000, 1000, '当场上存在「海」时，这张卡不受魔法效果的影响。'),
(45943123, 'Torpedo Takedown', '飞空鱼雷', 'エアー・トルピード', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只水属性超量怪兽为对象才能发动。那只怪兽1个超量素材取除，给与对方为自己手卡数量×400伤害。那只怪兽的攻击力直到回合结束时上升这个效果给与的伤害的数值。 ②：从自己墓地把这张卡和1只水属性超量怪兽除外才能发动。自己从卡组抽2张。'),
(79538761, 'Torque Tune Gear', '扭力调整齿轮', 'トルクチューン・ギア', 'Tuner Monster', 'Machine', 'LIGHT', 1, NULL, NULL, '①：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只表侧表示怪兽为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。 ②：装备怪兽的攻击力·守备力上升500，当作调整使用。'),
(7092142, 'Torrential Reborn', '激流苏生', '激流蘇生', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的水属性怪兽被战斗或者卡的效果破坏送去墓地时才能发动。那个时候被破坏从场上送去自己墓地的怪兽全部特殊召唤，给与对方基本分特殊召唤的怪兽数量×500的数值的伤害。「激流苏生」在1回合只能发动1张。'),
(53582587, 'Torrential Tribute', '激流葬', '激流葬', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：怪兽召唤·反转召唤·特殊召唤时才能发动。场上的怪兽全部破坏。'),
(75372290, 'Total Defense Shogun', '绝对防御将军', '絶対防御将軍', 'Effect Monster', 'Warrior', 'DARK', 6, 1550, 2500, '这张卡召唤·反转召唤成功的场合守备表示。这张卡可以在守备表示时攻击。守备表示攻击时用攻击力的数值计算伤害。'),
(71068247, 'Totem Bird', '图腾鸟', 'トーテムバード', 'XYZ Monster', 'Winged Beast', 'WIND', 3, 1900, 1400, '风属性3星怪兽×2 ①：魔法·陷阱卡发动时，把这张卡2个超量素材取除才能发动。那个发动无效并破坏。 ②：没有超量素材的这张卡的攻击力下降300。'),
(564541, 'Totem Dragon', '民艺龙', 'ミンゲイドラゴン', 'Effect Monster', 'Dragon', 'EARTH', 2, 400, 200, '龙族怪兽上级召唤的场合，这张卡可以作为2只的数量解放。自己的准备阶段时这张卡在墓地存在，自己场上没有怪兽存在的场合，可以把这张卡表侧攻击表示特殊召唤。这个效果在自己墓地有龙族以外的怪兽存在的场合不能发动。这个效果特殊召唤的这张卡从场上离开的场合从游戏中除外。'),
(56346071, 'Totem Five', '图腾五星', 'トーテム・ファイブ', 'Effect Monster', 'Rock', 'FIRE', 3, 500, 200, '①：包含这张卡的5只怪兽同时特殊召唤成功的场合发动。对方场上的卡全部破坏，给与对方破坏数量×500伤害。'),
(47873397, 'Totem Pole', '图腾柱', 'トーテムポール', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方不能把自己场上的原本攻击力是0的岩石族怪兽作为效果的对象。 ②：对方怪兽的攻击宣言时才能发动1次。那次攻击无效，给这张卡放置1个指示物。 ③：这张卡有3个指示物放置的场合，这张卡送去墓地。 ④：自己墓地有攻击力0的岩石族怪兽3种类以上存在的场合，把墓地的这张卡除外才能发动。这个回合，对方受到的效果伤害变成2倍。'),
(52823314, 'Tour Bus From the Underworld', '由魔界到现世的巴士', '魔界発現世行きバス', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 1000, '这张卡被送去墓地时，选择「由魔界到现世的巴士」以外的自己或者对方的墓地1只怪兽回到持有者卡组。'),
(89732524, 'Tour Bus To Forbidden Realms', '由魔界到冥界的巴士', '魔界発冥界行きバス', 'Flip Effect Monster', 'Fiend', 'DARK', 3, 600, 1000, '①：这张卡反转的场合发动。从卡组把1只光·暗属性以外的恶魔族怪兽加入手卡。'),
(10802915, 'Tour Guide From the Underworld', '魔界发现世行死亡向导', '魔界発現世行きデスガイド', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 600, '①：这张卡召唤时才能发动。从手卡·卡组把1只恶魔族·3星怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，不能作为同调素材。'),
(62784717, 'Tour of Doom', '死神的巡游', '死神の巡遊', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方回合的准备阶段时进行1次投掷硬币以下效果适用。 ●表：对方直到结束阶段时不能召唤·反转召唤。 ●里：自己在下次的自己回合不能召唤·反转召唤。'),
(94256039, 'Tower of Babel', '通天塔', 'バベル・タワー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。这张卡放置第4个魔力指示物时这张卡破坏，那个时候把魔法卡发动的玩家受到3000分伤害。'),
(48882106, 'Toxic Boxfish', '毒箱鲀', 'トックス・ボックス', 'Synchro Monster', 'Fish', 'WATER', 4, 1800, 800, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，以自己或对方的墓地1张卡为对象才能发动。那张卡除外。 ②：这张卡被除外的场合，以对方场上1张表侧表示卡为对象才能发动。那张卡的效果直到回合结束时无效。'),
(24878656, 'Toy Box', '玩具盒子', 'トイ・ボックス', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，可以从以下效果选择1个发动。 ●从自己的手卡·卡组·怪兽区域（表侧表示）·墓地选原本卡名包含「玩具」的持有可以把自身当作魔法卡使用从手卡到魔法与陷阱区域盖放效果的最多2只怪兽当作魔法卡使用在自己的魔法与陷阱区域盖放。 ●自己的魔法与陷阱区域最多2张卡破坏。 ②：1回合1次，对方怪兽的攻击宣言时，把自己场上1张里侧表示卡送去墓地才能发动。那只对方怪兽破坏。'),
(1826676, 'Toy Knight', '玩具骑士', 'トイナイト', 'Effect Monster', 'Machine', 'EARTH', 4, 200, 1200, '这张卡不能从卡组特殊召唤。对方场上的怪兽数量比自己场上的怪兽数量多的场合，这张卡可以从手卡特殊召唤。这张卡召唤·特殊召唤成功时，可以从手卡把1只「玩具骑士」特殊召唤。'),
(58132856, 'Toy Magician', '玩具魔术师', 'トイ・マジシャン', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1600, 1500, '这张卡可以当作魔法卡使用从手卡到魔法与陷阱卡区域盖放。自己的魔法与陷阱卡区域盖放的这张卡被对方的卡的效果破坏送去墓地的场合，那个回合的结束阶段时这张卡从墓地特殊召唤。此外，这张卡反转召唤成功时，把场上表侧表示存在的「玩具魔术师」的数量的场上存在的魔法·陷阱卡破坏。'),
(92607427, 'Toy Parade', '玩具游行队', 'トイ・パレード', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「魔玩具」卡使用。这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以从额外卡组特殊召唤的1只自己的暗属性怪兽为对象才能发动。这个回合，自己不用那只怪兽不能攻击宣言，那只怪兽每次战斗破坏怪兽送去墓地可以继续攻击。 ②：自己场上有天使族怪兽存在的场合，把墓地的这张卡除外才能发动。从自己墓地选1只4星以下的暗属性怪兽加入手卡。'),
(65504487, 'Toy Soldier', '玩具士兵', 'トイ・ソルジャー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 1000, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡可以当作魔法卡使用从手卡到魔法与陷阱区域盖放。 ②：魔法与陷阱区域盖放的这张卡被送去墓地的场合才能发动。这张卡特殊召唤。 ③：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「玩具箱子」加入手卡。自己场上有「玩具箱子」存在的场合，也能作为代替把1只光属性·4星怪兽加入手卡。'),
(69925461, 'Toy Tank', '玩具坦克', 'トイ・タンク', 'Effect Monster', 'Machine', 'LIGHT', 4, 1000, 2100, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡可以当作魔法卡使用从手卡到魔法与陷阱区域盖放。 ②：魔法与陷阱区域盖放的这张卡被送去墓地的场合才能发动。这张卡特殊召唤。 ③：把这张卡解放才能发动。从手卡把1只6星以下的怪兽特殊召唤。自己场上有「玩具箱子」存在的场合，也能作为代替从自己墓地把除「玩具坦克」外的1只6星以下的怪兽特殊召唤。'),
(70245411, 'Toy Vendor', '玩具罐', 'トイポット', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，丢弃1张手卡才能发动。自己从卡组抽1张，给双方确认。确认的卡是「毛绒动物」怪兽的场合，可以从手卡把1只怪兽特殊召唤。不是的场合，那张抽到的卡丢弃。 ②：这张卡被送去墓地的场合才能发动。从卡组把1只「锋利小鬼·剪刀」或者1只「毛绒动物」怪兽加入手卡。'),
(66226132, 'Trackblack', '引用通告黑鸟', 'トラックブラック', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1200, NULL, '效果怪兽2只 这个卡名的效果1回合只能使用1次。 ①：以这张卡所连接区1只自己怪兽为对象才能发动。这个回合，每次那只怪兽战斗破坏对方怪兽，自己从卡组抽1张。'),
(38120068, 'Trade-In', '抵价交易', 'トレード・イン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡丢弃1只8星怪兽才能发动。自己抽2张。'),
(23408872, 'Tradetoad', '替换蛙', 'サシカエル', 'Effect Monster', 'Aqua', 'WATER', 1, 100, 2000, '把自己场上存在的1只水族怪兽解放，选择自己墓地存在的1只名字带有「青蛙」的怪兽发动。选择的怪兽从墓地特殊召唤。这个效果1回合只能使用1次。'),
(63875853, 'Trading Places', '身份对换', '身分転換', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己基本分比对方多的场合，双方基本分交换。'),
(41248270, 'Traffic Ghost', '流量幽灵', 'トラフィックゴースト', 'Link Monster', 'Cyberse', 'DARK', NULL, 1800, NULL, '怪兽3只'),
(35686188, 'Tragedy', '断头台的惨剧', '断頭台の惨劇', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(81143465, 'Tragic Twin Twined Jewels', '哀哉玉绳双魂缱绻', 'あないみじや玉の緒ふたつ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '从额外卡组特殊召唤的自己场上的怪兽才能装备。 ①：比装备怪兽攻击力高的怪兽由对方从额外卡组特殊召唤的场合，以那之内的1只为对象才能发动。那只怪兽以及装备怪兽破坏，自己受到破坏的怪兽的原本攻击力合计数值的伤害。那之后，给与对方为和自己受到的伤害相同数值的伤害。'),
(98777036, 'Tragoedia', '悲怆魔', 'トラゴエディア', 'Effect Monster', 'Fiend', 'DARK', 10, -1, -1, '①：自己受到战斗伤害时才能发动。这张卡从手卡特殊召唤。 ②：这张卡的攻击力·守备力上升自己手卡数量×600。 ③：1回合1次，从手卡把1只怪兽送去墓地，以持有和那个等级相同等级的对方场上1只表侧表示怪兽为对象才能发动。得到那只表侧表示怪兽的控制权。 ④：1回合1次，以自己墓地1只怪兽为对象才能发动。这张卡的等级直到回合结束时变成和那只怪兽相同。'),
(60879050, 'Train Connection', '机关连接', '機関連結', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '把自己墓地2只10星以上的机械族怪兽除外发动的场合才能给机械族·地属性怪兽装备。 ①：装备怪兽的攻击力变成原本攻击力的2倍，装备怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：只要这张卡在魔法与陷阱区域存在，装备怪兽以外的自己怪兽不能攻击。'),
(37890974, 'Training Fur Hire, Fur All Your Training Needs', '空牙团的修炼', '空牙団の修練', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上的「空牙团」怪兽被战斗或者对方的效果破坏的场合，以那1只怪兽为对象才能发动。从卡组把持有比那只怪兽的原本等级低的等级的1只「空牙团」怪兽特殊召唤。'),
(42348802, 'Trakodon', '糙齿龙', 'トラコドン', 'Normal Monster', 'Dinosaur', 'EARTH', 3, 1300, 800, '虎型恐龙。跑过旷野的速度相当快。'),
(94283662, 'Trance Archfiend', '传送恶魔', 'トランス・デーモン', 'Effect Monster', 'Fiend', 'DARK', 4, 1500, 500, '①：1回合1次，自己主要阶段才能发动。从手卡丢弃1只恶魔族怪兽，这张卡的攻击力直到回合结束时上升500。 ②：自己场上的这张卡被破坏送去墓地时，以除外的1只自己的暗属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(14214060, 'Trance the Magic Swordsman', '魔法剑士 特兰斯', '魔法剣士トランス', 'Normal Monster', 'Spellcaster', 'EARTH', 6, 2600, 200, '实力相当强的奇特魔法师。好像从异空间旅行归来了。'),
(7969770, 'Trancefamiliar', '移魂使魔', 'トランスファミリア', 'Effect Monster', 'Psychic', 'DARK', 1, NULL, NULL, '①：1回合1次，以自己场上1只怪兽为对象才能发动。那只自己怪兽的位置向其他的自己的主要怪兽区域移动。'),
(6351147, 'Transaction Rollback', '事务回滚', 'トランザクション・ロールバック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把基本分支付一半，以「事务回滚」以外的对方墓地1张通常陷阱卡为对象才能发动。这个效果变成和那张通常陷阱卡发动时的效果相同。 ②：把墓地的这张卡除外，把基本分支付一半，以「事务回滚」以外的自己墓地1张通常陷阱卡为对象才能发动。这个效果变成和那张通常陷阱卡发动时的效果相同。'),
(25573054, 'Transcendent Wings', '进化之翼', '進化する翼', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己场上存在的1只「羽翼栗子球」和2张手卡送到墓地。从手卡·卡组特殊召唤1只「羽翼栗子球 LV10」上场。'),
(30128445, 'Transcendosaurus Drillygnathus', '超越恐龙 钻头矛颌龙', '超越竜ドリルグナトゥス', 'XYZ Monster', 'Dinosaur', 'WIND', 6, 3000, 2300, '6星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除，以除外的1只自己的恐龙族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：没有超量素材的这张卡用和怪兽的战斗给与对方的战斗伤害变成2倍。 ③：这张卡被破坏的场合才能发动。从自己墓地选1只通常怪兽回到卡组。那之后，可以把这张卡特殊召唤。'),
(56818742, 'Transcendosaurus Exaraptor', '超越恐龙 狂猛盗龙', '超越竜エグザラプトル', 'Link Monster', 'Dinosaur', 'DARK', NULL, 3000, NULL, '包含6星以上的怪兽的恐龙族怪兽2只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从手卡把1只恐龙族怪兽特殊召唤。 ②：这张卡所连接区的表侧表示的恐龙族怪兽被战斗破坏的场合或者被送去墓地的场合才能发动。自己抽1张。 ③：这张卡被破坏的场合才能发动。从自己墓地让1只通常怪兽回到卡组。那之后，可以把这张卡特殊召唤。'),
(67745632, 'Transcendosaurus Gigantozowler', '超越恐龙 十亿巨角龙', '超越竜ギガントザウラー', 'Fusion Monster', 'Dinosaur', 'EARTH', 12, 3800, 2000, '恐龙族怪兽＋通常怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，以自己墓地1只恐龙族怪兽为对象才能发动。那只怪兽加入手卡。这张卡从墓地特殊召唤的场合，可以再选自己的手卡·场上1张卡和对方场上1张卡破坏。 ②：这张卡被破坏的场合才能发动。从自己墓地选1只通常怪兽回到卡组。那之后，可以把这张卡特殊召唤。'),
(94130731, 'Transcendosaurus Glaciasaurus', '超越恐龙 冻雪龙', '超越竜グレイスザウルス', 'Synchro Monster', 'Dinosaur', 'WATER', 12, 3600, 2700, '调整＋调整以外的怪兽1只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡不会被战斗破坏。 ②：只要这张卡在怪兽区域存在，从墓地特殊召唤的自己场上的恐龙族怪兽不会成为对方的效果的对象，不会被对方的效果破坏。 ③：这张卡被破坏的场合才能发动。从自己墓地选1只通常怪兽回到卡组。那之后，可以把这张卡特殊召唤。'),
(31241087, 'Transcendosaurus Meteorus', '超越恐龙 厄兆陨龙', '超越竜メテオロス', 'Effect Monster', 'Dinosaur', 'FIRE', 12, 3500, 700, '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①②③的效果1回合各能使用1次。 ①：对方回合才能发动。选这张卡以外的自己的手卡·场上2只恐龙族怪兽破坏，这张卡从手卡特殊召唤。 ②：这张卡特殊召唤成功的场合才能发动。从卡组把1只恐龙族怪兽送去墓地。 ③：这张卡被破坏的场合才能发动。从自己墓地选1只通常怪兽回到卡组。那之后，可以把这张卡特殊召唤。'),
(1799464, 'Transcicada', '脱壳蝉', 'トランシケーダ', 'Tuner Monster', 'Insect', 'EARTH', 3, 800, 1000, '这个卡名的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。在自己场上把1只「蝉蜕衍生物」（昆虫族·地·3星·攻/守0）特殊召唤。只要这个效果特殊召唤的衍生物在怪兽区域存在，自己不是昆虫族怪兽不能从额外卡组特殊召唤。'),
(46947713, 'Transcode Talker', '转码语者', 'トランスコード・トーカー', 'Link Monster', 'Cyberse', 'EARTH', NULL, 2300, NULL, '效果怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡是互相连接状态的场合，这张卡以及这张卡所互相连接区的怪兽的攻击力上升500，对方不能把那些作为效果的对象。 ②：以除「转码语者」外的自己墓地1只连接3以下的电子界族连接怪兽为对象才能发动（这个效果发动的回合，自己不是电子界族怪兽不能特殊召唤）。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。'),
(66094973, 'Transforming Sphere', '变化气圈鸟', 'トランスフォーム・スフィア', 'Effect Monster', 'Winged Beast', 'WIND', 3, 100, 100, '1回合1次，选择对方场上表侧守备表示存在的1只怪兽才能发动。丢弃1张手卡，把选择的对方怪兽当作装备卡使用只有1只给这张卡装备。这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力数值。这张卡攻击的场合，战斗阶段结束时变成守备表示。结束阶段时，这张卡的效果装备的怪兽在对方场上表侧守备表示特殊召唤。'),
(44694191, 'Transient Masquerader of Illusion', NULL, NULL, 'Effect Monster', 'Illusion', 'EARTH', 8, 2400, NULL, NULL),
(66100045, 'Transmigration Break', '转生断绝', '転生断絶', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '从墓地回到卡组的卡不回到卡组从游戏中除外。'),
(58297729, 'Transmission Gear', '变则齿轮', '変則ギア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己怪兽和对方怪兽进行战斗的伤害计算时才能发动。和对方玩家进行猜拳。平局的场合重新猜拳。输的玩家必须把那只进行战斗的自身怪兽里侧表示除外。'),
(5288597, 'Transmodify', '升级转变', 'トランスターン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只表侧表示怪兽送去墓地才能发动。和墓地的那只怪兽种族·属性相同而等级高1星的1只怪兽从卡组特殊召唤。'),
(34072799, 'Transonic Bird', '跨音速鸟', 'トランソニックバード', 'Ritual Effect Monster', 'Winged Beast', 'DARK', 4, NULL, 2400, '「音速的追赶者」降临。 ①：1回合1次，可以发动。手卡1张仪式魔法卡给对方观看，把1只在那张卡有卡名记述的仪式怪兽从卡组加入手卡，给人观看的卡回到卡组。 ②：对方回合1次，从卡组把1张仪式魔法卡送去墓地才能发动。这个效果变成和那张仪式魔法卡发动时的仪式召唤效果相同。 ③：仪式召唤的这张卡被解放的场合，以对方场上1张表侧表示的卡为对象才能发动。那张卡的效果直到回合结束时无效。'),
(64697231, 'Trap Dustshoot', '滑槽', 'ダスト・シュート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方手卡是4张以上的场合才能发动。把对方手卡确认并选择1张怪兽卡，那张卡回到持有者卡组。'),
(13821299, 'Trap Eater', '陷阱吞噬者', 'トラップ・イーター', 'Tuner Monster', 'Fiend', 'DARK', 4, 1900, 1600, '这张卡不能通常召唤。把对方场上表侧表示存在的1张陷阱卡送去墓地的场合才能特殊召唤。'),
(24839398, 'Trap Gatherer', '陷阱集锦', 'トラップ・ギャザー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：装备怪兽的攻击力上升自己墓地的陷阱卡数量×400。 ②：装备怪兽战斗破坏对方怪兽的伤害计算后或者给与对方战斗伤害时，把这张卡送去墓地才能发动。从自己墓地把1张陷阱卡在自己场上盖放。 ③：自己场上的表侧表示的陷阱卡被效果破坏的场合，可以作为代替把场上的这张卡除外。'),
(4206964, 'Trap Hole', '落穴', '落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方对攻击力1000以上的怪兽的召唤·反转召唤成功时，以那1只怪兽为对象才能发动。那只攻击力1000以上的怪兽破坏。'),
(75902998, 'Trap Hole of Spikes', '穿刺的落穴', '串刺しの落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合召唤·特殊召唤的对方怪兽的攻击宣言时才能发动。那只攻击怪兽破坏，给与对方那只怪兽的原本攻击力一半数值的伤害。'),
(22377092, 'Trap Holic', '陷阱痴迷', 'トラップホリック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1张魔法·陷阱卡为对象才能发动。那张卡破坏，从卡组把「沉迷陷溺」以外的1张通常陷阱卡在自己场上盖放。这个效果盖放的卡只要自己墓地有陷阱卡3张以上存在，在盖放的回合也能发动。'),
(19252988, 'Trap Jammer', '陷阱干扰阵', 'トラップ・ジャマー', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '战斗阶段中才能发动。对方发动的陷阱卡的发动无效并破坏。'),
(46461247, 'Trap Master', '陷阱大师', 'トラップ・マスター', 'Flip Effect Monster', 'Warrior', 'EARTH', 3, 500, 1100, '反转：场上1张陷阱卡破坏。里侧表示翻开确认后破坏。'),
(3055837, 'Trap of Board Eraser', '黑板擦的陷阱', '黒板消しの罠', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '给与战斗伤害以外伤害的效果发动时才能发动。使自己所受的效果伤害无效，对方从手卡中选择1张丢弃。'),
(79766336, 'Trap of Darkness', '黑暗中的陷阱', '闇よりの罠', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己基本分是3000以下时，支付1000基本分，以「黑暗中的陷阱」以外的自己墓地1张通常陷阱卡为对象才能发动。这张卡的效果变成和那张墓地的通常陷阱卡发动时的效果相同。那之后，那张墓地的通常陷阱卡除外。'),
(80955168, 'Trap of the Imperial Tomb', '王墓的陷阱', '王墓の罠', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从对方墓地往自己场上有不死族怪兽特殊召唤时，以场上2张卡为对象才能发动。那些卡破坏。'),
(212652, 'Trap of the Poisonous Scorpion', '毒蝎的陷阱', '毒サソリの罠', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的直接攻击宣言时才能发动。那只怪兽破坏。那之后，给与对方300伤害。'),
(52286175, 'Trap Reactor Y FI', '陷阱反应机·空式', 'トラップ・リアクター・RR', 'Effect Monster', 'Machine', 'DARK', 4, 800, 1800, '对方把陷阱卡发动时才能发动。把那张陷阱卡破坏，给与对方基本分800分伤害。这个效果1回合只能使用1次。'),
(2122975, 'Trap Reclamation', '陷阱捕获', 'トラップ・キャプチャー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己把陷阱卡发动时，丢弃1张手卡连锁发动。连锁发动的陷阱卡被送去墓地时，那张卡回到手卡。'),
(59616123, 'Trap Stun', '陷阱无力化', 'トラップ・スタン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合，这张卡以外的场上的陷阱卡的效果无效化。'),
(70825459, 'Trap Tracks', '陷阱行迹', 'トラップトラック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只怪兽为对象才能发动。那只怪兽破坏，从卡组把「蛊惑陷迹」以外的1张通常陷阱卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。这张卡的发动后，直到回合结束时自己只能有1张陷阱卡发动。'),
(80101899, 'Trap Trick', '陷阱诡计', 'トラップトリック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把「蛊惑谋陷」以外的1张通常陷阱卡除外，那1张同名卡从卡组到自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。这张卡的发动后，直到回合结束时自己只能有1张陷阱卡发动。'),
(48805472, 'Traptantalizing Tune', '虫惑之诱', '蟲惑の誘い', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把1只昆虫族·植物族的4星怪兽或者1张通常陷阱卡从手卡丢弃才能发动。自己从卡组抽2张。 ②：把墓地的这张卡除外，以除外的自己1只昆虫族·植物族的4星怪兽或者1张通常陷阱卡为对象才能发动。那张卡回到卡组最下面。'),
(12801833, 'Traptrip Garden', '虫惑之园', '蟲惑の園', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己在通常召唤外加上只有1次，自己主要阶段可以把1只「虫惑魔」怪兽召唤。 ②：只要这张卡在场地区域存在，自己的昆虫族·植物族怪兽在1回合各有1次不会被战斗破坏。 ③：把自己场上1只怪兽除外才能发动。从自己的手卡·墓地选1只「虫惑魔」怪兽特殊召唤。'),
(59071624, 'Traptrix Allomerus', '树栖蚁之虫惑魔', 'アロメルスの蟲惑魔', 'XYZ Monster', 'Insect', 'EARTH', 4, 2200, 600, '4星怪兽×2只以上 这个卡名的②③的效果1回合各能使用1次。 ①：持有超量素材的这张卡不受陷阱卡的效果影响。 ②：把这张卡2个超量素材取除才能发动。从自己墓地选1只昆虫族·植物族的4星怪兽特殊召唤。 ③：自己的卡的效果让对方怪兽从场上离开，被送去墓地的场合或者被除外的场合，把这张卡1个超量素材取除，以那之内的1只为对象才能发动。那只怪兽在自己场上特殊召唤。'),
(75416738, 'Traptrix Arachnocampa', '光蕈之虫惑魔', 'キノの蟲惑魔', 'Effect Monster', 'Insect', 'EARTH', 4, 1300, 1500, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有「虫惑魔」怪兽存在的场合，自己·对方的主要阶段才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是昆虫族·植物族怪兽不能从额外卡组特殊召唤。 ②：这张卡只要在怪兽区域存在，不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。 ③：自己的魔法与陷阱区域盖放的卡在1回合各有1次不会被效果破坏。'),
(55428242, 'Traptrix Atrax', '漏斗网之虫惑魔', 'アトラの蟲惑魔', 'Effect Monster', 'Insect', 'EARTH', 4, 1800, 1000, '①：这张卡只要在怪兽区域存在，不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。 ②：只要这张卡在怪兽区域存在，自己可以把「洞」通常陷阱卡以及「落穴」通常陷阱卡从手卡发动。 ③：只要这张卡在怪兽区域存在，自己的通常陷阱卡的发动以及那些发动的效果不会被无效化。'),
(48183890, 'Traptrix Atypus', '穴蛛之虫惑魔', 'アティプスの蟲惑魔', 'Link Monster', 'Insect', 'EARTH', NULL, 1800, NULL, '包含昆虫族·植物族怪兽的怪兽2只以上 ①：连接召唤的这张卡不受陷阱卡的效果影响。 ②：只要自己墓地有通常陷阱卡存在，自己场上的「虫惑魔」怪兽的攻击力上升1000。 ③：1回合1次，以最多有自己场上的昆虫族·植物族怪兽数量的对方场上的表侧表示的卡为对象才能发动。那些卡的效果直到回合结束时无效。那之后，以下可以适用。 ●从自己墓地把1张通常陷阱卡除外，选作为对象的表侧表示的卡之内1张破坏。'),
(952523, 'Traptrix Cularia', '兔藻之虫惑魔', 'クラリアの蟲惑魔', 'Link Monster', 'Plant', 'EARTH', NULL, 1800, NULL, '昆虫族·植物族怪兽2只 这个卡名的②③的效果1回合各能使用1次。 ①：连接召唤的这张卡不受陷阱卡的效果影响。 ②：只要这张卡在怪兽区域存在，自己发动的「洞」通常陷阱卡以及「落穴」通常陷阱卡在发动后可以不送去墓地直接盖放。 ③：自己结束阶段，以自己墓地1只「虫惑魔」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(45803070, 'Traptrix Dionaea', '蝇狱之虫惑魔', 'ティオの蟲惑魔', 'Effect Monster', 'Plant', 'EARTH', 4, 1700, 1100, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时，以自己墓地1只「虫惑魔」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：这张卡特殊召唤成功时，以自己墓地1张「洞」通常陷阱卡或者「落穴」通常陷阱卡为对象才能发动。那张卡在自己场上盖放。那张卡在下次的自己回合的结束阶段除外。 ③：这张卡不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。'),
(88078306, 'Traptrix Genlisea', '旋狸之虫惑魔', 'リセの蟲惑魔', 'Effect Monster', 'Plant', 'EARTH', 4, 1200, 1600, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡只要在怪兽区域存在，不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。 ②：把这张卡解放才能发动。从自己的卡组以及墓地各选1张「洞」通常陷阱卡或者「落穴」通常陷阱卡在自己场上盖放（同名卡最多1张）。这个效果盖放的卡从场上离开的场合除外。'),
(74577599, 'Traptrix Holeutea', '空洞之虫惑魔爪', 'ホールティアの蟲惑魔', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。这张卡也能从手卡丢弃1张通常陷阱卡，在盖放的回合发动。 ①：这张卡发动后变成通常怪兽（植物族·地·4星·攻400/守2400）在怪兽区域守备表示特殊召唤（不当作陷阱卡使用）。 ②：把墓地的这张卡除外，以自己墓地1只「虫惑魔」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(82738277, 'Traptrix Mantis', '兰花之虫惑魔', 'ランカの蟲惑魔', 'Effect Monster', 'Insect', 'EARTH', 4, 1500, 1300, '①：这张卡召唤成功时才能发动。从卡组把1只「虫惑魔」怪兽加入手卡。 ②：这张卡只要在怪兽区域存在，不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。 ③：1回合1次，以自己场上盖放的1张魔法·陷阱卡为对象才能发动。盖放的那张卡回到持有者手卡。那之后，可以从手卡把1张魔法·陷阱卡盖放。这个效果在对方回合也能发动。'),
(91812341, 'Traptrix Myrmeleo', '蚁狮之虫惑魔', 'トリオンの蟲惑魔', 'Effect Monster', 'Insect', 'EARTH', 4, 1600, 1200, '①：这张卡召唤成功时才能发动。从卡组把1张「洞」通常陷阱卡或者「落穴」通常陷阱卡加入手卡。 ②：这张卡特殊召唤成功的场合，以对方场上1张魔法·陷阱卡为对象发动。那张对方的卡破坏。 ③：这张卡只要在怪兽区域存在，不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。'),
(28201945, 'Traptrix Nepenthes', '蜜笼之虫惑魔', 'カズーラの蟲惑魔', 'Effect Monster', 'Plant', 'EARTH', 4, 800, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡只要在怪兽区域存在，不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。 ②：自己把「洞」通常陷阱卡或者「落穴」通常陷阱卡发动的场合才能发动。从卡组选「卡祖拉之虫惑魔」以外的1只「虫惑魔」怪兽加入手卡或特殊召唤。'),
(1688285, 'Traptrix Pinguicula', '蜜堇之虫惑魔', 'シトリスの蟲惑魔', 'XYZ Monster', 'Plant', 'EARTH', 4, 2500, 300, '4星怪兽×2 这个卡名的②③的效果1回合各能使用1次。 ①：持有超量素材的这张卡不受和给这张卡作为超量素材中的怪兽相同种族的怪兽（除这张卡外）发动的效果以及陷阱卡的效果影响。 ②：把这张卡1个超量素材取除才能发动。从卡组把1只「虫惑魔」怪兽加入手卡。 ③：原本持有者是对方的怪兽被效果所送去墓地的场合或者所除外的场合才能发动。选那之内的1只作为这张卡的超量素材。'),
(49027020, 'Traptrix Pudica', '羞壶之虫惑魔', 'プティカの蟲惑魔', 'Effect Monster', 'Plant', 'EARTH', 4, 900, 1900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时才能发动。从卡组把1张「虫惑之园」加入手卡。 ②：这张卡特殊召唤成功的场合，以对方场上1只特殊召唤的怪兽为对象才能发动。那只怪兽除外。下次的准备阶段，对方可以选除外的1只自身怪兽特殊召唤。 ③：这张卡只要在怪兽区域存在，不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。'),
(6511113, 'Traptrix Rafflesia', '大王花之虫惑魔', 'フレシアの蟲惑魔', 'XYZ Monster', 'Plant', 'EARTH', 4, 300, 2500, '4星怪兽×2 ①：持有超量素材的这张卡不受陷阱卡的效果影响。 ②：只要这张卡在怪兽区域存在，「芙莉西亚之虫惑魔」以外的自己场上的「虫惑魔」怪兽不会被战斗·效果破坏，对方不能把那些作为效果的对象。 ③：自己·对方回合1次，把这张卡1个超量素材取除，从卡组把1张「洞」通常陷阱卡或「落穴」通常陷阱卡送去墓地才能发动。这个效果变成和那张陷阱卡发动时的效果相同。'),
(73639099, 'Traptrix Sera', '露珠之虫惑魔', 'セラの蟲惑魔', 'Link Monster', 'Plant', 'EARTH', NULL, 800, NULL, '连接怪兽以外的「虫惑魔」怪兽1只 这个卡名的②③的效果1回合各能使用1次。 ①：连接召唤的这张卡不受陷阱卡的效果影响。 ②：通常陷阱卡发动的场合才能发动。同名卡不在自己场上存在的1只「虫惑魔」怪兽从卡组特殊召唤。 ③：这张卡以外的自己的「虫惑魔」怪兽的效果发动的场合才能发动。从卡组把1张「洞」通常陷阱卡或「落穴」通常陷阱卡在自己场上盖放。'),
(29616929, 'Traptrix Trap Hole Nightmare', '虫惑落穴', '蟲惑の落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合特殊召唤的对方场上的怪兽把效果发动时才能发动。那个效果无效并破坏。'),
(28868394, 'Traptrix Vesiculo', '貉藻之虫惑魔', 'ジーナの蟲惑魔', 'Effect Monster', 'Plant', 'EARTH', 4, 1400, 1400, '这个卡名的①③的效果1回合只能有1次使用其中任意1个。 ①：把自己场上盖放的1张陷阱卡送去墓地才能发动。这张卡从手卡特殊召唤。 ②：这张卡只要在怪兽区域存在，不受「洞」通常陷阱卡以及「落穴」通常陷阱卡的效果影响。 ③：自己的魔法与陷阱区域没有卡存在的场合，把墓地的这张卡除外，以自己墓地1张「洞」通常陷阱卡或者「落穴」通常陷阱卡为对象才能发动。那张卡在自己场上盖放。'),
(99590524, 'Treacherous Trap Hole', '狡猾落穴', '狡猾な落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己墓地没有陷阱卡存在的场合，以场上2只怪兽为对象才能发动。那些怪兽破坏。'),
(54762426, 'Treasure Map', '埋藏金的地图', '埋蔵金の地図', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '要让盖放的这张卡回到手卡的效果发动时才能发动。从自己卡组抽2张卡，那之后丢弃1张手卡。'),
(45221020, 'Treasure Panda', '寻宝熊猫', 'トレジャー・パンダー', 'Effect Monster', 'Beast', 'EARTH', 4, 1100, 2000, '①：从自己墓地把最多3张魔法·陷阱卡里侧表示除外才能发动。和除外的卡数量相同等级的1只通常怪兽从卡组特殊召唤。'),
(84824728, 'Treasure Panther', '寻宝豹', 'トレジャー・パンサー', 'Flip Effect Monster', 'Beast', 'EARTH', 1, 100, 100, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡在手卡存在，场上有里侧守备表示怪兽存在的场合才能发动。这张卡特殊召唤。 ②：以场上最多3只里侧守备表示怪兽为对象才能发动。那些怪兽变成攻击表示。这个效果把3只怪兽变成攻击表示的场合，再给与对方900伤害。 ③：这张卡反转的场合才能发动。从卡组把1只通常怪兽送去墓地。'),
(69299029, 'Treasures of the Kings', '供奉王之遗宝的圣域', '王の遺宝祀りし聖域', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1张「阿匹卜」陷阱卡在自己场上盖放。 ②：这张卡只要在场地区域存在，卡名当作「王家的神殿」使用。 ③：1回合1次，自己场上有里侧表示卡2张以上存在的场合或者自己墓地有陷阱卡存在的场合才能发动。从卡组把有「王家的神殿」的卡名记述的1只怪兽加入手卡。'),
(13685271, 'Treaty on Uniform Nomenclature', '同姓同名同盟条约', '同姓同名同盟条約', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有衍生物以外的同名怪兽表侧表示2只以上存在的场合才能发动。那些同名怪兽的数量的以下效果适用。 ●2只：对方场上存在的1张魔法·陷阱卡破坏。 ●3只：对方场上存在的魔法·陷阱卡全部破坏。'),
(71759912, 'Tree Otter', '拉考拉', 'ラッコアラ', 'Effect Monster', 'Beast', 'WATER', 2, 1200, 100, '这张卡以外的兽族怪兽在自己场上表侧表示存在的场合，可以把自己场上表侧表示存在的1只怪兽的攻击力直到结束阶段时上升1000。这个效果1回合只能使用1次。'),
(12538374, 'Treeborn Frog', '黄泉青蛙', '黄泉ガエル', 'Effect Monster', 'Aqua', 'WATER', 1, 100, 100, '①：这张卡在墓地存在，自己场上没有「黄泉青蛙」存在的场合，自己准备阶段才能发动。这张卡特殊召唤。这个效果在自己场上没有魔法·陷阱卡存在的场合才能发动和处理。'),
(46918794, 'Tremendous Fire', '火炎地狱', '火炎地獄', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方受到1000分的伤害，自己受到500分的伤害。');